    39	export const makeCodexDirectProvider = Effect.gen(
    40	  function* makeCodexDirectProviderService() {
    41	    const oauth = yield* CodexOAuthService;
    42	    const requestMapper = yield* CodexRequestMapper;
    43	    const httpClient = yield* CodexHttpClient;
    44	    const streamMapper = yield* CodexStreamMapper;
    45	
    46	    return CodexDirectProvider.of({
    47	      streamChatCompletion: Effect.fn(
    48	        "CodexDirectProvider.streamChatCompletion"
    49	      )(function* (input: CodexDirectProviderInput) {
    50	        const request = yield* requestMapper.toCodexResponses(input.request);
    51	        const credential = yield* oauth.getValidCredential(input.subject);
    52	        const response = yield* httpClient
    53	          .postResponsesStream({
    54	            accessToken: credential.accessToken,
    55	            accountId: credential.accountId,
    56	            request,
    57	          })
    58	          .pipe(
    59	            Effect.catchTags({
    60	              CodexHttpStatusError: (error) =>
    61	                error.status !== 401
    62	                  ? Effect.fail(error)
    63	                  : Effect.gen(function* recoverRejectedCredential() {
    64	                      const recovered = yield* oauth.recoverAfterUnauthorized({
    65	                        subject: input.subject,
    66	                        observedCredentialRevision:
    67	                          credential.credentialRevision,
    68	                      });
    69	
    70	                      return yield* httpClient
    71	                        .postResponsesStream({
    72	                          accessToken: recovered.accessToken,
    73	                          accountId: recovered.accountId,
    74	                          request,
    75	                        })
    76	                        .pipe(
    77	                          Effect.catchTags({
    78	                            CodexHttpStatusError: (retryError) =>
    79	                              retryError.status === 401
    80	                                ? Effect.fail(
    81	                                    new CodexReauthenticationRequired({
    82	                                      profileId: input.subject.profileId,
    83	                                      message:
    84	                                        "Codex subscription authorization requires a new trusted-local login.",
    85	                                    })
    86	                                  )
    87	                                : Effect.fail(retryError),
    88	                          })
    89	                        );
    90	                    }),
    91	            })
    92	          );
    93	
    94	        return yield* streamMapper.toOpenAICompatibleStream({
    95	          model: input.request.model,
    96	          body: response.body,
    97	        });
    98	      }),
    99	    });
   100	  }
   101	).pipe(Effect.withSpan("CodexDirectProviderLive"));
